export const supabaseVideoService={async create(businessId:string,input:ClipCreateInput,file:File){let path='';try{path=await uploadBusinessAsset('deal-media',businessId,file);const{data,error}=await requireSupabase().from('deal_clips').insert({business_id:businessId,deal_id:input.dealId||null,video_path:path,caption:input.caption,music:input.music||null,status:'published'}).select('id').single();fail(error);return str(data?.id);}catch(error){await removeAsset('deal-media',path);throw error;}},async getAll(){const{data,error}=await requireSupabase().from('deal_clips').select('*, businesses(name,username,logo_url,category,location), deals(title)').eq('status','published').order('created_at',{ascending:false});fail(error);return rows(data).map(mapClip);},async getByBusiness(id:string){return(await this.getAll()).filter((item)=>item.businessId===id);},async toggleLike(id:string){await toggleOwn('deal_clip_likes','clip_id',id);return(await this.getAll()).find((item)=>item.id===id)??null;},async toggleSave(id:string){await toggleOwn('saved_deal_clips','clip_id',id);return(await this.getAll()).find((item)=>item.id===id)??null;} };
function mapClip(value:unknown):VideoClip{const r=row(value),b=row(r.businesses),d=row(r.deals);return{id:str(r.id),businessId:str(r.business_id),businessName:str(b.name),businessUsername:str(b.username),businessAvatar:publicAsset('business-logos',b.logo_url),businessLogo:publicAsset('business-logos',b.logo_url),businessCategory:str(b.category),businessLocation:str(b.location),videoUrl:publicAsset('deal-media',r.video_path),thumbnailUrl:publicAsset('deal-media',r.thumbnail_path),caption:str(r.caption),dealId:str(r.deal_id)||undefined,dealTitle:str(d.title)||undefined,likeCount:0,commentCount:0,shareCount:0,saveCount:0,isLiked:false,isSaved:false,isFollowing:false,music:str(r.music)||undefined,createdAt:iso(r.created_at)};}

export const supabaseTemplateService={async getAll(){const{data,error}=await requireSupabase().from('business_templates').select('*').eq('is_active',true);fail(error);return rows(data).map(mapTemplate);},async getById(id:TemplateId){return(await this.getAll()).find((item)=>item.id===id)??(await this.getAll())[0];}};
function mapTemplate(value:unknown):BusinessTemplateConfig{const r=row(value),c=row(r.configuration);return{id:str(r.key) as TemplateId,name:str(r.name),description:str(c.description),accentColor:str(c.accentColor,'#109a59'),fontFamily:str(c.fontFamily,'Inter'),heroStyle:str(c.heroStyle,'minimal') as BusinessTemplateConfig['heroStyle'],cardStyle:str(c.cardStyle,'rounded') as BusinessTemplateConfig['cardStyle'],sectionOrder:Array.isArray(c.sectionOrder)?c.sectionOrder.map(String):['about','featured','hours','location','reviews'],imageTreatment:str(c.imageTreatment,'natural') as BusinessTemplateConfig['imageTreatment'],defaultThemeMode:str(c.defaultThemeMode,'light') as BusinessTemplateConfig['defaultThemeMode']};}
export const supabaseCategoryService={async getAll():Promise<Category[]>{return staticCategories;}};

export const supabaseCustomerService={async getCurrent():Promise<CustomerAccount>{const uid=await userId();const{data,error}=await requireSupabase().from('profiles').select('*').eq('id',uid).single();fail(error);const r=row(data);const[follows,rewards,reviews,saved]=await Promise.all([count('business_followers','customer_id',uid),count('reward_claims','customer_id',uid),count('reviews','customer_id',uid),count('saved_posts','customer_id',uid)]);return{id:uid,displayName:str(r.display_name),email:str(r.email_private),avatarUrl:publicAsset('customer-avatars',r.avatar_url),createdAt:iso(r.created_at),lastActiveAt:new Date().toISOString(),followingCount:follows,rewardsCount:rewards,reviewsCount:reviews,savedCount:saved,status:str(r.status,'active') as CustomerAccount['status']};}};
async function count(table:string,column:string,value:string){const{count,error}=await requireSupabase().from(table).select('*',{count:'exact',head:true}).eq(column,value);fail(error);return count??0;}
export const supabaseOwnerService={async getCurrent():Promise<BusinessOwner>{const uid=await userId();const{data,error}=await requireSupabase().from('profiles').select('*').eq('id',uid).single();fail(error);const businesses=await supabaseBusinessService.getByOwner(uid);const r=row(data);return{id:uid,name:str(r.display_name),email:str(r.email_private),phone:'',businessIds:businesses.map((item)=>item.id)};}};

export const supabaseSubscriptionService={async getByBusiness(id:string){const{data,error}=await requireSupabase().from('subscriptions').select('*, businesses(name)').eq('business_id',id).maybeSingle();fail(error);return data?mapSubscription(data):null;},async getPayments(id:string){const{data,error}=await requireSupabase().from('payments').select('*, businesses(name), invoices(invoice_number)').eq('business_id',id).order('created_at',{ascending:false});fail(error);return rows(data).map(mapPayment);} };
function mapSubscription(value:unknown):Subscription{const r=row(value),b=row(r.businesses);return{id:str(r.id),businessId:str(r.business_id),businessName:str(b.name),plan:str(r.plan,'lite') as Subscription['plan'],status:subscriptionUiStatus(str(r.status)),startDate:iso(r.started_at),expiryDate:iso(r.current_period_end),nextBillingDate:str(r.current_period_end)||str(r.subscription_start_at)||undefined,amount:Number(r.monthly_amount_paise??0)/100,autoRenew:r.autopay_authorized===true&&r.cancel_at_period_end!==true,setupFeePaid:Boolean(r.setup_fee_paid),setupFeeAmount:Number(r.setup_fee_amount_paise??0)/100,monthlyAmount:Number(r.monthly_amount_paise??0)/100,autopayAuthorized:Boolean(r.autopay_authorized),providerStatus:str(r.provider_status),totalCount:Number(r.total_count??0),paidCount:Number(r.paid_count??0),cancelAtPeriodEnd:Boolean(r.cancel_at_period_end),activationType:str(r.activation_type,'pending') as Subscription['activationType']};}
function subscriptionUiStatus(value:string):Subscription['status']{return value==='active'?'active':value==='past_due'?'failed':value==='grace_period'?'expiring':value==='cancelled'?'suspended':'expired';}
function mapPayment(value:unknown):Payment{const r=row(value),b=row(r.businesses),invoice=rows(r.invoices)[0]??{};return{id:str(r.external_payment_id,str(r.id)),businessId:str(r.business_id),businessName:str(b.name),amount:num(r.amount),type:str(r.type) as Payment['type'],status:str(r.status) as Payment['status'],date:iso(r.created_at),invoiceId:str(invoice.invoice_number),method:str(r.provider)};}

export const supabaseAdminService={async getDashboardMetrics():Promise<AnalyticsMetric[]>{const[b,c,s,p]=await Promise.all([countAll('businesses'),countAll('profiles','role','customer'),countAll('subscriptions','status','active'),countAll('payments','status','failed')]);return[{label:'Total Businesses',value:b,change:0,trend:'flat'},{label:'Total Customers',value:c,change:0,trend:'flat'},{label:'Active Pro',value:s,change:0,trend:'flat'},{label:'Failed Payments',value:p,change:0,trend:'flat'}];},getBusinesses:businessQuery,async getCustomers(){const{data,error}=await requireSupabase().from('profiles').select('*').eq('role','customer');fail(error);return rows(data).map((r):CustomerAccount=>({id:str(r.id),displayName:str(r.display_name),email:str(r.email_private),avatarUrl:str(r.avatar_url),createdAt:iso(r.created_at),lastActiveAt:iso(r.updated_at),followingCount:0,rewardsCount:0,reviewsCount:0,savedCount:0,status:str(r.status) as CustomerAccount['status']}));},async getPayments(){const{data,error}=await requireSupabase().from('payments').select('*, businesses(name), invoices(invoice_number)');fail(error);return rows(data).map(mapPayment);},async getSubscriptions(){const{data,error}=await requireSupabase().from('subscriptions').select('*, businesses(name)');fail(error);return rows(data).map(mapSubscription);},async getReports(){const client=requireSupabase();const{data,error}=await client.from('reports').select('*').order('created_at',{ascending:false});fail(error);const reportRows=rows(data);const reporterIds=[...new Set(reportRows.map((r)=>str(r.reporter_id)).filter(Boolean))];const profiles=new Map<string,Row>();if(reporterIds.length){const result=await client.from('profiles').select('id,display_name,avatar_url').in('id',reporterIds);fail(result.error);for(const profile of rows(result.data))profiles.set(str(profile.id),profile);}return reportRows.map((r):Report=>{const p=profiles.get(str(r.reporter_id))??{};return{id:str(r.id),reporterName:str(p.display_name),reporterAvatar:str(p.avatar_url),entityType:str(r.entity_type) as Report['entityType'],entityId:str(r.entity_id),entityPreview:str(r.details),reason:str(r.reason) as Report['reason'],status:str(r.status) as Report['status'],createdAt:iso(r.created_at)};});}};
async function countAll(table:string,column?:string,value?:string){let query=requireSupabase().from(table).select('*',{count:'exact',head:true});if(column&&value)query=query.eq(column,value);const{count,error}=await query;fail(error);return count??0;}

export const supabaseAnalyticsService={async getOwnerMetrics(businessId:string):Promise<{metrics:AnalyticsMetric[];series:AnalyticsSeries[];trafficSources:TrafficSource[]}>{const client=requireSupabase(),since=new Date(Date.now()-30*86400000).toISOString();const [followers,newFollowers,relationships,requests,bills,paid,coins,eventsResult]=await Promise.all([countAll('business_followers','business_id',businessId),client.from('business_followers').select('*',{count:'exact',head:true}).eq('business_id',businessId).gte('followed_at',since),countAll('customer_business_relationships','business_id',businessId),countAll('bill_requests','business_id',businessId),countAll('bills','business_id',businessId),client.from('bills').select('final_amount,customer_id').eq('business_id',businessId).eq('payment_status','paid'),client.from('fe_coin_accounts').select('balance').eq('business_id',businessId).eq('account_type','business').maybeSingle(),client.from('analytics_events').select('event_type,metadata,created_at').eq('business_id',businessId).gte('created_at',since)]);fail(newFollowers.error);fail(paid.error);fail(coins.error);fail(eventsResult.error);const paidRows=rows(paid.data),sales=paidRows.reduce((sum,item)=>sum+num(item.final_amount),0),repeatCustomers=[...new Set(paidRows.map((item)=>str(item.customer_id)))].filter((customer)=>paidRows.filter((item)=>str(item.customer_id)===customer).length>1).length;const metrics:AnalyticsMetric[]=[{label:'Followers',value:followers,change:0,trend:'flat'},{label:'New followers',value:newFollowers.count??0,change:0,trend:'flat'},{label:'Total customers',value:relationships,change:0,trend:'flat'},{label:'Bill requests',value:requests,change:0,trend:'flat'},{label:'Bills created',value:bills,change:0,trend:'flat'},{label:'Paid bills',value:paidRows.length,change:0,trend:'flat'},{label:'Attributed sales',value:sales,change:0,trend:'flat',format:'currency'},{label:'Repeat customers',value:repeatCustomers,change:0,trend:'flat'},{label:'FE Coins',value:num(coins.data?.balance),change:0,trend:'flat'}];const events=rows(eventsResult.data),series:AnalyticsSeries[]=[{label:'Activity (30 days)',data:Array.from({length:30},(_,index)=>{const date=new Date(Date.now()-(29-index)*86400000),key=date.toISOString().slice(0,10);return{label:date.toLocaleDateString(undefined,{month:'short',day:'numeric'}),value:events.filter((item)=>str(item.created_at).slice(0,10)===key).length};})}];return{metrics,series,trafficSources:[]};}};

export const supabaseStaticServices = { category: supabaseCategoryService };
